:root {
  --primary: #176b63;
  --secondary: #10534d;
  --accent: #e7efea;
  --dark: #173c38;
  --page-bg: #f7f5ef;
  --bs-body-font-family: 'Manrope', system-ui, sans-serif;
  --bs-body-color: #263e3a;
  --bs-body-bg: var(--page-bg);
}

body {
  margin: 0;
  background-color: var(--page-bg);
  color: #263e3a;
  font-family: 'Manrope', system-ui, sans-serif;
  line-height: 1.7;
}

h1, h2, h3, h6, .navbar-brand {
  font-family: 'Manrope', system-ui, sans-serif;
  line-height: 1.2;
  letter-spacing: -0.035em;
  overflow-wrap: anywhere;
}

.row > * { min-width: 0; }
section { scroll-margin-top: 1.5rem; }
section.py-5 { padding-block: clamp(3rem, 6vw, 5.5rem) !important; }
.navbar { padding-block: 1.1rem; background-color: var(--dark); }
.navbar > .container { gap: 0.75rem; }
.navbar-brand { margin: 0; white-space: normal; max-width: calc(100% - 4.5rem); }
.navbar-brand, .nav-link { color: #fff !important; }
.navbar-nav { gap: 0.25rem 1rem; }
.nav-link { padding-block: 0.65rem; }
.nav-link:hover { color: #c5e6da !important; }
.navbar-toggler { flex-shrink: 0; border-color: #8baba4; }
.navbar-toggler-icon { filter: invert(1) grayscale(1) brightness(2); }
.navbar-collapse { min-width: 0; }

.hero { background-color: #e7efea; }
.display-heading { font-size: clamp(2.35rem, 5vw, 4.4rem); line-height: 1.08; margin-bottom: 1.5rem; }
.section-title { color: var(--dark); font-size: clamp(1.85rem, 3vw, 2.75rem); margin-bottom: 1.5rem; }
.lead { font-size: 1.125rem; line-height: 1.8; }
.hero .lead { max-width: 34rem; margin-bottom: 1.75rem; }
.text-muted { color: #586b65 !important; }
img { display: block; max-width: 100%; height: auto; }
.hero img, #about img { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: 1rem !important; }
#services { background-color: #eaece2; }
#services .row > div { display: flex; }
.card-service { width: 100%; height: 100%; padding: 1.75rem 1.25rem !important; border: 1px solid #d6dfd4; border-top: 4px solid var(--primary); border-radius: 0.85rem; background: #fffef9; }
.card-service h6 { font-size: 1.05rem; line-height: 1.4; margin-bottom: 0.85rem; }
.card-service p { line-height: 1.7; }
#testimonial { background: var(--page-bg); }
.hero-dark { background-color: var(--dark); color: #fff; }
.btn-brand { padding: 0.8rem 1.4rem; background-color: var(--primary); border-color: var(--primary); color: #fff; font-weight: 700; border-radius: 0.5rem; white-space: normal; }
.btn-brand:hover, .btn-brand:focus-visible { background-color: var(--secondary); border-color: var(--secondary); color: #fff; }
.hero-dark .btn-brand { background: #d9eabb; border-color: #d9eabb; color: var(--dark); }
.hero-dark .btn-brand:hover { background: #c4dba0; border-color: #c4dba0; }
a:focus-visible, button:focus-visible { outline: 3px solid #b18b39; outline-offset: 4px; }
footer { background-color: #102e2b; color: #e3eae4; }

@media (min-width: 768px) {
  .hero .row, #about .row { --bs-gutter-x: 3rem; }
}

@media (max-width: 575.98px) {
  .container { padding-inline: 1.25rem; }
  .navbar-brand { font-size: 1.15rem !important; }
  .display-heading { font-size: 2.5rem; }
  .hero img, #about img { margin-top: 0.5rem; }
  #contact .btn { max-width: 100%; font-size: 1rem; }
}
